ENCODER_STATE_HASH = 'e26bfa7738beb32e415ff88c7da73fc95dfcdcdcc6bab3d19d7c3019b0319150'


def _flatten(values):
    for value in values:
        if isinstance(value, list):
            yield from _flatten(value)
        else:
            yield value


def _shape(values):
    shape = []
    while isinstance(values, list):
        shape.append(len(values))
        values = values[0] if values else []
    return shape


def _float32_hex(value):
    return struct.pack(">f", float(value)).hex()


def canonical_encoder_state_hash(tensors):
    """Return the canonical SHA-256 fingerprint of this encoder state."""
    rows = []
    for name in sorted(tensors):
        values = tensors[name]
        rows.append([name, _shape(values), "float32", [_float32_hex(value) for value in _flatten(values)]])
    payload = {
        "schema_version": SCHEMA_VERSION,
        "architecture": [[key, ARCHITECTURE[key]] for key in ARCHITECTURE],
        "tensors": rows,
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return hashlib.sha256(encoded.encode()).hexdigest()
